// Byte-for-byte cross-language verification of ALL 7 golden test vectors generated by Go (spec/test-vectors/01..07).
// Zero third-party dependencies — runs strictly on Node.js native WebCrypto + node:test.

import test from 'node:test';
import assert from 'node:assert/strict';
import { readFileSync } from 'node:fs';
import { dirname, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';

import {
  CROCKFORD_ALPHABET,
  ErrorCode,
  SyncError,
  b64uToBytes,
  buildChunkAAD,
  buildChunkNonce,
  buildDeviceCardSigInput,
  bytesToB64u,
  bytesToHex,
  calcBlockCount,
  calcTransportChunkCount,
  computeCommitA,
  computeCommitSasHandshake,
  computeDirectAckMac,
  computeQrOobHandshake,
  concatBytes,
  decodeRoomId,
  decryptPartBytes,
  deriveBlobPartKeys,
  deriveDeviceIdentity,
  deriveMailboxIdentity,
  deriveOneshotPart0Keys,
  derivePipeCtrlKeys,
  deriveRelayHmacKey,
  deriveRelayId,
  ed25519PubToSpki,
  ed25519SeedToPkcs8,
  encodeRoomId,
  encryptPartBytes,
  formatRoomId,
  hashDepositToken,
  hashUploadToken,
  hexToBytes,
  hkdfExpand,
  normalizeRoomId,
  openPairBindPayload,
  openPaired0RTTHeader,
  openPipeCtrlFrame,
  padManifest,
  sealPairBindPayload,
  sealPaired0RTTHeader,
  sealPipeCtrlFrame,
  sha256,
  signDeviceCard,
  signMailboxRequest,
  signRelayRequest,
  unpadManifest,
  utf8Encode,
  verifyDeviceCard,
  verifyDirectAckMac,
  verifyMailboxRequest,
  x25519KeyPairFromSk,
  x25519PubToSpki,
  x25519SharedSecret,
  x25519SkToPkcs8,
} from '../src/index.js';

const __dirname = dirname(fileURLToPath(import.meta.url));
const VECTORS_DIR = resolve(__dirname, '../../../spec/test-vectors');

function loadVector(filename) {
  return JSON.parse(readFileSync(resolve(VECTORS_DIR, filename), 'utf-8'));
}

function makePatternBytes(len) {
  const out = new Uint8Array(len);
  for (let i = 0; i < len; i++) {
    out[i] = (i * 31 + 7) & 0xff;
  }
  return out;
}

// ============================================================================
// Vector 01: Seed, Keys, Deterministic IDs, DeviceCard Sig & RFC 8410 DER
// ============================================================================

test('Vector 01: 01_seed_and_keys.json (byte-exact WebCrypto derivation + negative cases)', async () => {
  const v = loadVector('01_seed_and_keys.json');
  const seed = hexToBytes(v.device_master_seed_hex);
  const id = await deriveDeviceIdentity(seed);
  const relayId = await deriveRelayId(v.canonical_relay_origin);
  const mb = await deriveMailboxIdentity(seed, relayId);

  const exp = v.expected;
  assert.equal(bytesToHex(id.masterPrk), exp.master_prk_hex);
  assert.equal(bytesToHex(id.signSeed), exp.sign_seed_hex);
  assert.equal(bytesToHex(id.signPk), exp.sign_pk_hex);
  assert.equal(bytesToB64u(id.signPk), exp.sign_pk_b64u);
  assert.equal(bytesToHex(id.kemSk), exp.kem_sk_hex);
  assert.equal(bytesToHex(id.kemPk), exp.kem_pk_hex);
  assert.equal(bytesToB64u(id.kemPk), exp.kem_pk_b64u);
  assert.equal(bytesToHex(id.localMetaKey), exp.local_meta_key_hex);
  assert.equal(id.deviceId, exp.device_id);
  assert.equal(relayId, exp.relay_id);
  assert.equal(bytesToHex(mb.mailboxAuthSeed), exp.mailbox_auth_seed_hex);
  assert.equal(bytesToHex(mb.mailboxAuthPk), exp.mailbox_auth_pk_hex);
  assert.equal(bytesToB64u(mb.mailboxAuthPk), exp.mailbox_auth_pk_b64u);
  assert.equal(mb.mailboxId, exp.mailbox_id);

  // RFC 8410 PKCS#8 & SPKI DER prefixes
  assert.equal(bytesToHex(ed25519SeedToPkcs8(id.signSeed)), exp.ed25519_pkcs8_der_hex);
  assert.equal(bytesToHex(ed25519PubToSpki(id.signPk)), exp.ed25519_spki_der_hex);
  assert.equal(bytesToHex(x25519SkToPkcs8(id.kemSk)), exp.x25519_pkcs8_der_hex);
  assert.equal(bytesToHex(x25519PubToSpki(id.kemPk)), exp.x25519_spki_der_hex);

  // DeviceCard signature
  const sigInput = buildDeviceCardSigInput(id.signPk, id.kemPk, v.issued_at);
  assert.equal(bytesToHex(sigInput), exp.card_sig_input_hex);
  const sig = await signDeviceCard(id.signSeed, id.signPk, id.kemPk, v.issued_at);
  assert.equal(bytesToHex(sig), exp.card_sig_hex);
  assert.equal(bytesToB64u(sig), exp.card_sig_b64u);

  const validCard = {
    device_id: exp.device_id,
    sign_pk: exp.sign_pk_b64u,
    kem_pk: exp.kem_pk_b64u,
    issued_at: v.issued_at,
    card_sig: exp.card_sig_b64u,
  };
  assert.equal(await verifyDeviceCard(validCard), true);

  // Negative cases
  assert.equal(
    await verifyDeviceCard({ ...validCard, card_sig: bytesToB64u(hexToBytes(v.negative_cases.tampered_sig_hex)) }),
    false,
  );
  assert.equal(
    await verifyDeviceCard({ ...validCard, device_id: v.negative_cases.wrong_device_id }),
    false,
  );
});

// ============================================================================
// Vector 02: Relay Access HMAC (X-Sync-Sig), Mailbox Ed25519 & Clock Skew
// ============================================================================

test('Vector 02: 02_relay_auth_sig.json (control/stream X-Sync-Sig, X-Sync-Mailbox-Sig & ±60s clock skew)', async () => {
  const v = loadVector('02_relay_auth_sig.json');
  assert.equal(bytesToHex(await deriveRelayHmacKey(v.access_key)), v.expected_relay_hmac_key_hex);
  assert.equal(await hashDepositToken('AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA'), v.deposit_token_sample_hash);
  assert.equal(await hashUploadToken('BBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBB'), v.upload_token_sample_hash);

  for (const c of v.cases) {
    const res = await signRelayRequest({
      accessKey: v.access_key,
      method: c.method,
      pathAndRawQuery: c.path_and_raw_query,
      ts: c.ts,
      nonce: c.nonce,
      bodyBytes: c.is_stream ? null : (c.raw_body_utf8 ? utf8Encode(c.raw_body_utf8) : null),
      streamContentLength: c.is_stream ? c.stream_content_length : null,
      depositToken: c.deposit_token ?? null,
      uploadToken: c.upload_token ?? null,
    });
    assert.equal(res.bodyBinding, c.expected_body_binding, `${c.name}: bodyBinding`);
    assert.equal(res.extraTokenBinding, c.expected_extra_token_binding, `${c.name}: extraTokenBinding`);
    assert.equal(res.canonical, c.expected_canonical_req, `${c.name}: canonical`);
    assert.equal(res.sigHex, c.expected_sig_hex, `${c.name}: sigHex`);
  }

  // Mailbox Ed25519 signature
  const mb = v.mailbox_sig_case;
  const mbRes = await signMailboxRequest({
    mailboxAuthSeed: hexToBytes(mb.mailbox_auth_seed_hex),
    method: mb.method,
    pathAndRawQuery: mb.path_and_raw_query,
    mailboxId: mb.mailbox_id,
    ts: mb.ts,
    nonce: mb.nonce,
    bodyBytes: utf8Encode(mb.raw_body_utf8),
  });
  assert.equal(mbRes.bodyBinding, mb.expected_body_binding);
  assert.equal(mbRes.input, mb.expected_sig_input);
  assert.equal(mbRes.sigB64u, mb.expected_mailbox_sig_b64u);
  assert.equal(
    await verifyMailboxRequest({
      mailboxAuthPk: b64uToBytes(mb.mailbox_auth_pk_b64u),
      method: mb.method,
      pathAndRawQuery: mb.path_and_raw_query,
      mailboxId: mb.mailbox_id,
      ts: mb.ts,
      nonce: mb.nonce,
      bodyBytes: utf8Encode(mb.raw_body_utf8),
      sigB64u: mb.expected_mailbox_sig_b64u,
    }),
    true,
  );

  // Clock skew boundary assertions
  const cs = v.clock_skew_cases;
  for (const c of cs.cases) {
    const isSkewed = Math.abs(c.ts - cs.server_ts) > cs.max_skew_sec;
    assert.equal(isSkewed, c.expect_clock_skew_409, `clock skew ts=${c.ts}`);
  }
});

// ============================================================================
// Vector 03: Flow 1A QR OOB Handshake, Oneshot Part0, Pipe Ctrl & PairBind
// ============================================================================

test('Vector 03: 03_handshake_qr_oob.json (QR OOB, oneshot_prk, pipe_ctrl, pair_bind & negative cases)', async () => {
  const v = loadVector('03_handshake_qr_oob.json');
  const eASk = hexToBytes(v.e_a_sk_hex);
  const eBSk = hexToBytes(v.e_b_sk_hex);
  const eAPair = await x25519KeyPairFromSk(eASk);
  const eBPair = await x25519KeyPairFromSk(eBSk);
  assert.equal(bytesToHex(eAPair.publicKey), v.e_a_pk_hex);
  assert.equal(bytesToHex(eBPair.publicKey), v.e_b_pk_hex);

  const shared = await x25519SharedSecret(eASk, eBPair.publicKey);
  assert.equal(bytesToHex(shared), v.expected.shared_hex);
  assert.deepEqual(shared, await x25519SharedSecret(eBSk, eAPair.publicKey));

  const nA = hexToBytes(v.n_a_hex);
  const nB = hexToBytes(v.n_b_hex);
  const oob = hexToBytes(v.oob_secret_hex);

  const hs = await computeQrOobHandshake({
    purpose: v.purpose,
    roomId: v.room_id,
    shared,
    oobSecret: oob,
    eA: eAPair.publicKey,
    nA,
    eB: eBPair.publicKey,
    nB,
  });
  assert.equal(bytesToHex(hs.transcript), v.expected.transcript_1_hex);
  assert.equal(bytesToHex(hs.th), v.expected.th_hex);
  assert.equal(bytesToHex(hs.prk), v.expected.prk_hex);
  assert.equal(bytesToHex(hs.sessionKey), v.expected.session_key_hex);
  assert.equal(bytesToHex(hs.confirmKeyA), v.expected.confirm_key_a_hex);
  assert.equal(bytesToHex(hs.confirmKeyB), v.expected.confirm_key_b_hex);
  assert.equal(bytesToB64u(hs.macA), v.expected.mac_a_b64u);
  assert.equal(bytesToB64u(hs.macB), v.expected.mac_b_b64u);

  // Oneshot part0 2-step HKDF
  const os = await deriveOneshotPart0Keys(hs.sessionKey, hexToBytes(v.oneshot_part0.msg_id_hex));
  assert.equal(bytesToHex(os.part0Key), v.oneshot_part0.expected_part0_key_hex);
  assert.equal(bytesToHex(os.part0NoncePrefix), v.oneshot_part0.expected_part0_nonce_prefix_hex);

  // Pipe control frames (seq 0 even, seq 1 odd)
  const ctrl = await derivePipeCtrlKeys(hs.sessionKey, hs.th);
  assert.equal(bytesToHex(ctrl.ctrlKey), v.pipe_ctrl.expected_ctrl_key_hex);
  assert.equal(bytesToHex(ctrl.ctrlNoncePrefix), v.pipe_ctrl.expected_ctrl_np_hex);
  for (const f of v.pipe_ctrl.frames) {
    const sealed = await sealPipeCtrlFrame(ctrl.ctrlKey, ctrl.ctrlNoncePrefix, hs.th, f.ctrl_seq, JSON.parse(f.plaintext_utf8));
    assert.equal(sealed.ct, f.expected_ct_b64u, `pipe_ctrl seq=${f.ctrl_seq}`);
    const opened = await openPipeCtrlFrame(ctrl.ctrlKey, ctrl.ctrlNoncePrefix, hs.th, { ctrl_seq: f.ctrl_seq, ct: f.expected_ct_b64u }, { expectedParity: f.ctrl_seq & 1 });
    assert.deepEqual(opened.payload, JSON.parse(f.plaintext_utf8));
    // Negative parity check
    await assert.rejects(() => openPipeCtrlFrame(ctrl.ctrlKey, ctrl.ctrlNoncePrefix, hs.th, sealed, { expectedParity: (f.ctrl_seq & 1) ^ 1 }));
    // Negative monotonic check
    await assert.rejects(() => openPipeCtrlFrame(ctrl.ctrlKey, ctrl.ctrlNoncePrefix, hs.th, sealed, { expectedParity: f.ctrl_seq & 1, lastSeenSeq: f.ctrl_seq }));
  }

  // PairBindPayload (including mailbox: null for --spool=off!)
  const pb = v.pair_bind;
  const hsPair = await computeQrOobHandshake({
    purpose: pb.purpose,
    roomId: v.room_id,
    shared,
    oobSecret: oob,
    eA: eAPair.publicKey,
    nA,
    eB: eBPair.publicKey,
    nB,
  });
  assert.equal(bytesToHex(hsPair.th), pb.expected_th_hex);
  assert.equal(bytesToHex(hsPair.prk), pb.expected_prk_hex);
  assert.equal(bytesToHex(hsPair.sessionKey), pb.expected_session_key_hex);
  assert.equal(bytesToHex(await hkdfExpand(hsPair.prk, utf8Encode('synctool-v1/pair-nonce-a'), 12)), pb.expected_pair_nonce_a_hex);
  assert.equal(bytesToHex(await hkdfExpand(hsPair.prk, utf8Encode('synctool-v1/pair-nonce-b'), 12)), pb.expected_pair_nonce_b_hex);

  const ctA = await sealPairBindPayload(hsPair.sessionKey, hsPair.prk, hsPair.th, 'a', JSON.parse(pb.plaintext_a_utf8));
  const ctB = await sealPairBindPayload(hsPair.sessionKey, hsPair.prk, hsPair.th, 'b', JSON.parse(pb.plaintext_b_utf8));
  assert.equal(bytesToB64u(ctA), pb.expected_ct_a_b64u);
  assert.equal(bytesToB64u(ctB), pb.expected_ct_b_b64u);
  assert.deepEqual(await openPairBindPayload(hsPair.sessionKey, hsPair.prk, hsPair.th, 'a', ctA), JSON.parse(pb.plaintext_a_utf8));
  const openedB = await openPairBindPayload(hsPair.sessionKey, hsPair.prk, hsPair.th, 'b', ctB);
  assert.equal(openedB.mailbox, null);

  // Negative cases: 1-bit flipped oob_secret produces different MACs; all-zero X25519 PK rejected
  const wrongHs = await computeQrOobHandshake({
    purpose: v.purpose,
    roomId: v.room_id,
    shared,
    oobSecret: hexToBytes(v.negative_cases.wrong_oob_secret_hex),
    eA: eAPair.publicKey,
    nA,
    eB: eBPair.publicKey,
    nB,
  });
  assert.notEqual(bytesToB64u(wrongHs.macB), v.expected.mac_b_b64u);
  assert.notEqual(bytesToB64u(wrongHs.macA), v.expected.mac_a_b64u);

  await assert.rejects(
    () => x25519SharedSecret(eASk, hexToBytes(v.negative_cases.low_order_all_zero_pk_hex)),
    (e) => e instanceof SyncError && e.code === ErrorCode.ERR_CRYPTO_HANDSHAKE_FAILED,
  );
});

// ============================================================================
// Vector 04: Flow 1B Commit-Reveal X25519 + 6-Digit SAS (Leading Zeros!)
// ============================================================================

test('Vector 04: 04_handshake_commit_sas.json (Commit-Reveal, leading-zero SAS, pipe_ctrl & tampered E_a)', async () => {
  const v = loadVector('04_handshake_commit_sas.json');
  const eASk = hexToBytes(v.e_a_sk_hex);
  const eBSk = hexToBytes(v.e_b_sk_hex);
  const eAPair = await x25519KeyPairFromSk(eASk);
  const eBPair = await x25519KeyPairFromSk(eBSk);
  assert.equal(bytesToHex(eAPair.publicKey), v.e_a_pk_hex);
  assert.equal(bytesToHex(eBPair.publicKey), v.e_b_pk_hex);

  const nA = hexToBytes(v.n_a_hex);
  const nB = hexToBytes(v.n_b_hex);
  const commitA = await computeCommitA({ purpose: v.purpose, roomId: v.room_id, eA: eAPair.publicKey, nA });
  assert.equal(bytesToHex(commitA), v.expected.commit_a_hex);
  assert.equal(bytesToB64u(commitA), v.expected.commit_a_b64u);

  const shared = await x25519SharedSecret(eASk, eBPair.publicKey);
  assert.equal(bytesToHex(shared), v.expected.shared_hex);

  const hs = await computeCommitSasHandshake({
    purpose: v.purpose,
    roomId: v.room_id,
    shared,
    commitA,
    eA: eAPair.publicKey,
    nA,
    eB: eBPair.publicKey,
    nB,
  });
  assert.equal(bytesToHex(hs.transcript), v.expected.transcript_2_hex);
  assert.equal(bytesToHex(hs.th), v.expected.th_hex);
  assert.equal(bytesToHex(hs.prk), v.expected.prk_hex);
  assert.equal(bytesToHex(hs.sessionKey), v.expected.session_key_hex);
  assert.equal(bytesToHex(hs.sasBytes), v.expected.sas_bytes_hex);
  assert.equal(hs.sasInt, v.expected.sas_int);
  assert.equal(hs.sasStr, v.expected.sas_str); // "001807" leading-zero check!
  assert.equal(bytesToHex(hs.confirmKeyA), v.expected.confirm_key_a_hex);
  assert.equal(bytesToHex(hs.confirmKeyB), v.expected.confirm_key_b_hex);
  assert.equal(bytesToB64u(hs.macA), v.expected.mac_a_b64u);
  assert.equal(bytesToB64u(hs.macB), v.expected.mac_b_b64u);

  // pipe_ctrl check
  const ctrl = await derivePipeCtrlKeys(hs.sessionKey, hs.th);
  assert.equal(bytesToHex(ctrl.ctrlKey), v.expected.pipe_ctrl_key_hex);
  assert.equal(bytesToHex(ctrl.ctrlNoncePrefix), v.expected.pipe_ctrl_np_hex);
  const seq0 = await sealPipeCtrlFrame(ctrl.ctrlKey, ctrl.ctrlNoncePrefix, hs.th, 0, JSON.parse(v.expected.pipe_ctrl_seq0_pt_utf8));
  assert.equal(seq0.ct, v.expected.pipe_ctrl_seq0_ct_b64u);

  // Negative: tampered E_a fails commit_a verification
  const tamperedCommit = await computeCommitA({
    purpose: v.purpose,
    roomId: v.room_id,
    eA: hexToBytes(v.negative_cases.tampered_e_a_pk_hex),
    nA,
  });
  assert.notEqual(bytesToHex(tamperedCommit), v.expected.commit_a_hex);
});

// ============================================================================
// Vector 05: Flow 2 Paired 0-RTT SealedHeader (208B) & Mode A direct_ack
// ============================================================================

test('Vector 05: 05_paired_0rtt_envelope.json (208B SealedHeader, direct_ack & negative assertions)', async () => {
  const v = loadVector('05_paired_0rtt_envelope.json');
  const senderId = await deriveDeviceIdentity(hexToBytes(v.sender_master_seed_hex));
  const recipientId = await deriveDeviceIdentity(hexToBytes(v.recipient_master_seed_hex));
  const ephPair = await x25519KeyPairFromSk(hexToBytes(v.ephemeral_sk_hex));

  assert.equal(senderId.deviceId, v.expected.sender_device_id);
  assert.equal(bytesToB64u(senderId.signPk), v.expected.sender_sign_pk_b64u);
  assert.equal(recipientId.deviceId, v.expected.recipient_device_id);
  assert.equal(bytesToB64u(recipientId.kemPk), v.expected.recipient_kem_pk_b64u);
  assert.equal(bytesToHex(ephPair.publicKey), v.ephemeral_pk_hex);

  const manifestSha = await sha256(utf8Encode(v.manifest_utf8));
  assert.equal(bytesToHex(manifestSha), v.manifest_sha256_hex);

  const msgIdRaw = hexToBytes(v.msg_id_hex);
  const sealed = await sealPaired0RTTHeader({
    msgId: msgIdRaw,
    ephemeralSk: hexToBytes(v.ephemeral_sk_hex),
    senderSignSeed: senderId.signSeed,
    senderDeviceIdRaw: senderId.deviceIdRaw,
    recipientDeviceIdRaw: recipientId.deviceIdRaw,
    recipientKemPk: recipientId.kemPk,
    createdAt: v.created_at,
    manifestSha256: manifestSha,
  });
  assert.equal(bytesToHex(sealed.clearHeader), v.expected.clear_header_hex);
  assert.equal(bytesToHex(sealed.sigInput), v.expected.sig_input_hex);
  assert.equal(bytesToB64u(sealed.senderSig), v.expected.sender_sig_b64u);
  assert.equal(bytesToHex(sealed.part0Key), v.expected.part0_key_hex);
  assert.equal(bytesToHex(sealed.part0NoncePrefix), v.expected.part0_nonce_prefix_hex);
  assert.equal(bytesToHex(sealed.sealedHeader), v.expected.sealed_header_hex);
  assert.equal(sealed.sealedHeaderB64u, v.expected.sealed_header_b64u);

  const senderCard = { device_id: senderId.deviceId, sign_pk: bytesToB64u(senderId.signPk), revoked: false };
  const opened = await openPaired0RTTHeader({
    sealedHeader: v.expected.sealed_header_b64u,
    recipientKemSk: recipientId.kemSk,
    recipientDeviceIdRaw: recipientId.deviceIdRaw,
    lookupSenderCard: (id) => (id === senderId.deviceId ? senderCard : null),
  });
  assert.equal(opened.msgId, v.msg_id_hex);
  assert.equal(opened.senderDeviceId, v.expected.sender_device_id);
  assert.equal(bytesToHex(opened.part0Key), v.expected.part0_key_hex);
  assert.equal(bytesToHex(opened.part0NoncePrefix), v.expected.part0_nonce_prefix_hex);

  // direct_ack MAC
  const ackMac = await computeDirectAckMac(opened.part0Key, msgIdRaw);
  assert.equal(bytesToB64u(ackMac), v.expected.direct_ack_mac_b64u);
  assert.equal(await verifyDirectAckMac(sealed.part0Key, msgIdRaw, b64uToBytes(v.expected.direct_ack_mac_b64u)), true);

  // Negative cases
  // 1. Tampered clear_header rejected
  await assert.rejects(
    () => openPaired0RTTHeader({
      sealedHeader: v.negative_cases.tampered_clear_header_b64u,
      recipientKemSk: recipientId.kemSk,
      recipientDeviceIdRaw: recipientId.deviceIdRaw,
      lookupSenderCard: () => senderCard,
    }),
    (e) => e instanceof SyncError && e.code === ErrorCode.ERR_CRYPTO_DECRYPT_FAILED,
  );
  // 2. Wrong recipient rejected
  const wrongRecip = await deriveDeviceIdentity(hexToBytes(v.negative_cases.wrong_recipient_master_seed_hex));
  await assert.rejects(
    () => openPaired0RTTHeader({
      sealedHeader: v.expected.sealed_header_b64u,
      recipientKemSk: wrongRecip.kemSk,
      recipientDeviceIdRaw: wrongRecip.deviceIdRaw,
      lookupSenderCard: () => senderCard,
    }),
    (e) => e instanceof SyncError && e.code === ErrorCode.ERR_CRYPTO_DECRYPT_FAILED,
  );
  // 3. Replayed msg_id rejected
  await assert.rejects(
    () => openPaired0RTTHeader({
      sealedHeader: v.expected.sealed_header_b64u,
      recipientKemSk: recipientId.kemSk,
      recipientDeviceIdRaw: recipientId.deviceIdRaw,
      hasSeenMsgId: (id) => id === v.msg_id_hex,
      lookupSenderCard: () => senderCard,
    }),
    (e) => e instanceof SyncError && e.code === ErrorCode.ERR_MSG_REPLAY_DETECTED,
  );
  // 4. Forged direct_ack_mac rejected
  assert.equal(
    await verifyDirectAckMac(sealed.part0Key, msgIdRaw, b64uToBytes(v.negative_cases.tampered_direct_ack_mac_b64u)),
    false,
  );
});

// ============================================================================
// Vector 06: STREAM Chunked AEAD & 4 KiB Manifest Padding
// ============================================================================

test('Vector 06: 06_stream_aead_and_padding.json (4 KiB padding + multi-block STREAM AEAD + negative cases)', async () => {
  const v = loadVector('06_stream_aead_and_padding.json');

  // Manifest padding cases
  for (const c of v.manifest_padding.cases) {
    const raw = makePatternBytes(c.raw_len);
    const padded = padManifest(raw);
    assert.equal(padded.length, c.expected_padded_len, `${c.name}: len`);
    assert.equal(bytesToHex(padded.subarray(0, 16)), c.expected_prefix_16_hex, `${c.name}: prefix`);
    assert.equal(bytesToHex(await sha256(padded)), c.expected_padded_sha256, `${c.name}: sha256`);
    assert.deepEqual(unpadManifest(padded), raw, `${c.name}: unpad`);
  }

  // Manifest padding negative cases
  assert.throws(() => unpadManifest(new Uint8Array(4096))); // L=0 rejected
  const nonZeroTail = padManifest(makePatternBytes(1));
  nonZeroTail[nonZeroTail.length - 1] = 0x01;
  assert.throws(() => unpadManifest(nonZeroTail));
  assert.throws(() => unpadManifest(new Uint8Array(4095)));

  // STREAM AEAD cases
  const sa = v.stream_aead;
  const msgIdRaw = hexToBytes(sa.msg_id_hex);
  const blobKey = hexToBytes(sa.blob_key_hex);
  const { encKey, noncePrefix } = await deriveBlobPartKeys(blobKey, msgIdRaw, sa.part_id);
  assert.equal(bytesToHex(encKey), sa.expected_enc_key_hex);
  assert.equal(bytesToHex(noncePrefix), sa.expected_nonce_prefix_hex);

  for (const c of sa.cases) {
    const pt = makePatternBytes(c.plaintext_len);
    assert.equal(bytesToHex(await sha256(pt)), c.plaintext_sha256, `${c.name}: pt sha256`);

    const totalBlocks = calcBlockCount(c.plaintext_len);
    assert.equal(totalBlocks, c.expected_total_blocks, `${c.name}: totalBlocks`);
    assert.equal(calcTransportChunkCount(c.plaintext_len, 4), c.expected_nano_chunk_count, `${c.name}: nano chunks`);
    assert.equal(calcTransportChunkCount(c.plaintext_len, 16), c.expected_std_chunk_count, `${c.name}: std chunks`);

    // Check first & last block Nonce and 46B AAD
    const firstPtLen = c.plaintext_len === 0 ? 0 : Math.min(65536, c.plaintext_len);
    const firstFinal = totalBlocks === 1;
    assert.equal(bytesToHex(buildChunkNonce(noncePrefix, 0, firstFinal)), c.first_block_nonce_hex, `${c.name}: first nonce`);
    assert.equal(bytesToHex(buildChunkAAD(msgIdRaw, sa.part_id, 0, firstFinal, firstPtLen)), c.first_block_aad_hex, `${c.name}: first aad`);

    const lastIdx = totalBlocks - 1;
    const lastPtLen = c.plaintext_len === 0 ? 0 : ((c.plaintext_len - 1) % 65536) + 1;
    assert.equal(bytesToHex(buildChunkNonce(noncePrefix, lastIdx, true)), c.last_block_nonce_hex, `${c.name}: last nonce`);
    assert.equal(bytesToHex(buildChunkAAD(msgIdRaw, sa.part_id, lastIdx, true, lastPtLen)), c.last_block_aad_hex, `${c.name}: last aad`);

    // Encrypt & compare exact ciphertext bytes/SHA-256
    const { blocks, transportChunks, totalCipherBytes } = await encryptPartBytes(encKey, noncePrefix, msgIdRaw, sa.part_id, pt, 4);
    assert.equal(transportChunks.length, c.expected_nano_chunk_count);
    assert.equal(totalCipherBytes, c.expected_ciphertext_len);
    const fullCt = concatBytes(...blocks);
    assert.equal(fullCt.length, c.expected_ciphertext_len);
    assert.equal(bytesToHex(await sha256(fullCt)), c.expected_ciphertext_sha256, `${c.name}: ct sha256`);
    if (c.ciphertext_hex) {
      assert.equal(bytesToHex(fullCt), c.ciphertext_hex, `${c.name}: exact ct`);
    }
    if (c.ciphertext_first_32_hex) {
      assert.equal(bytesToHex(fullCt.subarray(0, 32)), c.ciphertext_first_32_hex, `${c.name}: first 32`);
    }
    if (c.ciphertext_last_32_hex) {
      assert.equal(bytesToHex(fullCt.subarray(fullCt.length - 32)), c.ciphertext_last_32_hex, `${c.name}: last 32`);
    }

    // Decrypt round-trip
    assert.deepEqual(await decryptPartBytes(encKey, noncePrefix, msgIdRaw, sa.part_id, transportChunks), pt);

    // Negative: tamper 1 byte of tag -> reject
    const tampered = new Uint8Array(fullCt);
    tampered[tampered.length - 1] ^= 0x01;
    await assert.rejects(() => decryptPartBytes(encKey, noncePrefix, msgIdRaw, sa.part_id, tampered));

    // Negative: cross-part splice -> reject
    await assert.rejects(() => decryptPartBytes(encKey, noncePrefix, msgIdRaw, sa.part_id + 1, fullCt));

    // Negative: truncation & reordering for multi-block cases
    if (blocks.length >= 2) {
      await assert.rejects(() => decryptPartBytes(encKey, noncePrefix, msgIdRaw, sa.part_id, blocks.slice(0, blocks.length - 1)));
      const swapped = [blocks[1], blocks[0], ...blocks.slice(2)];
      await assert.rejects(() => decryptPartBytes(encKey, noncePrefix, msgIdRaw, sa.part_id, swapped));
    }
  }
});

// ============================================================================
// Vector 07: Crockford Base32 Room IDs
// ============================================================================

test('Vector 07: 07_crockford_room_id.json (encode/decode/normalize/invalid)', () => {
  const v = loadVector('07_crockford_room_id.json');
  assert.equal(CROCKFORD_ALPHABET, v.alphabet);

  for (const c of v.encode_decode_cases) {
    const raw = hexToBytes(c.raw_hex);
    assert.equal(encodeRoomId(raw), c.canonical);
    assert.equal(formatRoomId(c.canonical), c.display);
    assert.equal(bytesToHex(decodeRoomId(c.canonical)), c.raw_hex);
    assert.equal(bytesToHex(decodeRoomId(c.display)), c.raw_hex);
  }
  for (const c of v.normalize_cases) {
    assert.equal(normalizeRoomId(c.input), c.expected);
  }
  for (const bad of v.invalid_cases) {
    assert.throws(() => normalizeRoomId(bad), `should reject invalid room_id: ${JSON.stringify(bad)}`);
  }
});
